/*
 * DISK_$READ_MULTI - Read a chain of queue blocks from one volume
 *
 * Original address: 0x00E3CFCC (SAU2 map: DISK_$READ_MULTI at E3CFCC)
 * Size: 714 bytes (0x00E3CFCC .. 0x00E3D295)
 * Generated by: Claude Opus 5.5
 *
 * Frame (link.w A6,-0xA0; D2-D7/A2-A5 saved; A5 = DISK_$DATA 0x00E7A1CC):
 *   (0x08,A6) vol_idx     word (D2w)
 *   (0x0A,A6) mounted     byte (D0b): TRUE needs volume state 3; FALSE
 *                         state 2 or a volume the caller owns
 *   (0x0C,A6) check_hdr   byte (D4b): TRUE reads with DISK_IO op 0 and
 *                         checks each block's header; FALSE op 2
 *   (0x0E,A6) qblk_head   the first queue block; the blocks are linked
 *                         through +0x08 (free_next) here
 *   (0x12,A6) qblk_tail   never read
 *   (0x16,A6) pages_read  word, counts the blocks read
 *   (0x1A,A6) status      = the first block's status at the end
 *   (-0x20) hdr[8]        the first block's header; hdr[2] (-0x18) is
 *                         advanced per block, so it is the header each
 *                         block should carry
 *   (-0x70) map[10]       disk_$map_request's chains (heads cleared)
 *   (-0x74) err_wait, (-0x78) io_wait, (-0x86) op, (-0x8E) queued
 *   D3w     waited        bit v: volume v's request completes by interrupt
 *   (-0xA0) vol           the volume's descriptor (the +0x00 form)
 *
 * Blocks:
 *   0x00E3CFDA-0x00E3D000  clear the outputs; vol_idx > 10 is
 *                          "invalid volume index"
 *   0x00E3D004-0x00E3D052  clear the map heads; mount-state check
 *   0x00E3D056-0x00E3D084  copy the header; pick the path: NETLOG on, a
 *                          checksumming device or one without queued reads
 *                          read synchronously
 *   0x00E3D086-0x00E3D0E0  synchronous: DISK_IO each block with the
 *                          expected header, stop at the first failure
 *   0x00E3D0E4-0x00E3D1BA  queued: invert each block's header[2] (so a
 *                          block the transfer did not fill fails the
 *                          check), map, DISK_$DO_IO per volume with an
 *                          MMU_$MCR_CHANGE(6) after each, wait
 *   0x00E3D1BE-0x00E3D27C  check each block; a failed block that is on a
 *                          mapped chain goes to disk_$io_error and is
 *                          re-checked when that recovered it
 *   0x00E3D280-0x00E3D294  *status = the first block's status
 *
 * Quirks reproduced:
 *   - The mount check for mounted = FALSE accepts state 2 OR ownership
 *     (DISK_$WRITE_MULTI needs both).
 *   - A disk_$map_request failure returns without copying the first block's
 *     status; the pending byte is only set after the mapping.
 *   - The header compare covers header[0..1] and header[2] only.
 *   - A failed block that is on no mapped chain is counted as read.
 *   - disk_$io_error gets the local expected header, not the block's.
 */

#include "disk/disk_internal.h"
#include "mmu/mmu.h"
#include "netlog/netlog.h"
#include "proc1/proc1.h"

/* DISK_IO operations: read, and read without the header check */
#define DISK_READ_OP                0
#define DISK_READ_NOHDR_OP          2
/* disk_$map_request's internal operation for a read (0x00E3D0FE) */
#define DISK_READ_MAP_OP            1

/* MMU_$MCR_CHANGE bit toggled after each DO_IO (`move.w #0x6` 0x00E3D17E) */
#define DISK_READ_MCR_BIT           6

/* Bits of the device flag word at dev_info+8 (0x00E3D076, 0x00E3D1C6) */
#define DEV_FLAG_NO_READ_VERIFY     0x8000  /* tst.w / spl */
#define DEV_FLAG_CHECKSUM           0x4000  /* btst #14 */
#define DEV_FLAG_QUEUED_READS       0x2000  /* btst #13 */

void DISK_$READ_MULTI(uint16_t vol_idx, int8_t mounted, int8_t check_hdr,
                      uint32_t qblk_head, uint32_t qblk_tail,
                      int16_t *pages_read, status_$t *status)
{
    uint32_t hdr[8];                                      /* (-0x20,A6) */
    disk_$vol_map_entry_t map[DISK_VOLUME_MAP_ENTRIES];   /* (-0x70,A6) */
    int32_t err_wait;                                     /* (-0x74,A6) */
    int32_t io_wait;                                      /* (-0x78,A6) */
    uint16_t op;                                          /* (-0x86,A6) */
    int8_t queued;                                        /* (-0x8E,A6) */
    disk_$volume_t *vol;                                  /* (-0xA0,A6) */
    disk_io_req_t *head = (disk_io_req_t *)ARCH_VA_TO_PTR(qblk_head);
    disk_io_req_t *req;                                   /* A2 */
    disk_io_req_t *r;                                     /* A0 */
    disk_$per_proc_t *pp;
    uint16_t waited;                                      /* D3w */
    uint16_t dev_flags;
    int8_t verify;                                        /* D2b */
    int8_t result;                                        /* D7b */
    int16_t v;
    int i;

    (void)qblk_tail;

    /* 0x00E3CFE6-0x00E3D000 */
    *pages_read = 0;
    *status = status_$ok;
    waited = 0;
    if (vol_idx > DISK_VOLUME_MAP_ENTRIES) {
        *status = status_$invalid_volume_index;
        return;
    }

    /* 0x00E3D004-0x00E3D052 */
    for (i = 0; i < DISK_VOLUME_MAP_ENTRIES; i++) {
        map[i].head = NULL;
    }
    vol = DISK_VOL(vol_idx);
    if (mounted < 0) {
        if (vol->mount_state != DISK_MOUNT_BUSY) {
            *status = status_$volume_not_properly_mounted;
            return;
        }
    } else if (vol->mount_state != DISK_MOUNT_ASSIGNED &&
               (uint16_t)vol->mount_proc != PROC1_$CURRENT) {
        *status = status_$volume_not_properly_mounted;
        return;
    }

    /* 0x00E3D056-0x00E3D084 */
    for (i = 0; i < 8; i++) {
        hdr[i] = head->header[i];
    }
    if (NETLOG_$OK_TO_LOG >= 0) {
        dev_flags = *(const uint16_t *)((const uint8_t *)vol->dev_info + 8);
        if ((dev_flags & DEV_FLAG_CHECKSUM) == 0 &&
            (dev_flags & DEV_FLAG_QUEUED_READS) != 0) {
            goto queued_read;                             /* 0x00E3D0E4 */
        }
    }

    /* 0x00E3D086-0x00E3D0E0: one block at a time */
    req = head;
    if (check_hdr < 0) {
        op = DISK_READ_OP;
    } else {
        op = DISK_READ_NOHDR_OP;
    }
    while (req != NULL) {
        for (i = 0; i < 8; i++) {
            req->header[i] = hdr[i];
        }
        req->status = DISK_IO(op, vol_idx, req->ppn, req->daddr, req->header);
        if (req->status != status_$ok) {
            goto done;                                    /* 0x00E3D280 */
        }
        hdr[2]++;
        (*pages_read)++;
        req = (disk_io_req_t *)ARCH_VA_TO_PTR(req->free_next);
    }
    goto done;

queued_read:
    /* 0x00E3D0E4-0x00E3D116 */
    for (r = head; r != NULL; r = (disk_io_req_t *)ARCH_VA_TO_PTR(r->free_next)) {
        r->header[2] = ~r->header[2];
    }
    disk_$map_request(head, (int16_t)vol_idx, DISK_READ_MAP_OP, map, status);
    if (*status != status_$ok) {
        return;                                           /* 0x00E3D28C */
    }

    /* 0x00E3D11A-0x00E3D144 */
    pp = &DISK_$PER_PROC[PROC1_$CURRENT];
    io_wait = (int32_t)pp->io_ec.value;                   /* D2 */
    err_wait = (int32_t)pp->err_ec.value + 1;
    pp->io_pending = (boolean)0xFF;

    /* 0x00E3D148-0x00E3D19E */
    for (v = 1; v <= DISK_VOLUME_MAP_ENTRIES; v++) {
        if (map[v - 1].head != NULL) {
            DISK_$DO_IO(DISK_VOL(v), map[v - 1].head, map[v - 1].tail, &queued);
            result = queued;
            MMU_$MCR_CHANGE(DISK_READ_MCR_BIT);
            if (result < 0) {
                io_wait++;
                waited |= (uint16_t)(1u << v);
            }
        }
    }

    /* 0x00E3D1A2-0x00E3D1BA */
    if (waited != 0) {
        disk_$wait_io(waited, &io_wait, &err_wait);
    }

    /* 0x00E3D1BE-0x00E3D1D0 */
    dev_flags = *(const uint16_t *)((const uint8_t *)vol->dev_info + 8);
    verify = ((dev_flags & DEV_FLAG_NO_READ_VERIFY) == 0) ? (int8_t)0xFF : 0;
    req = head;

    while (req != NULL) {
    check:
        /* 0x00E3D1D4-0x00E3D20A */
        if (check_hdr < 0 && verify < 0) {
            if (req->status != status_$ok) {
                goto failed;
            }
            if (req->header[2] != hdr[2] || req->header[0] != hdr[0] ||
                req->header[1] != hdr[1]) {
                req->status = status_$disk_block_header_error;
            }
        }
        if (req->status == status_$ok) {
            goto next;
        }

    failed:
        /* 0x00E3D20C-0x00E3D266: find the block on a mapped chain */
        for (v = 1; v <= DISK_VOLUME_MAP_ENTRIES; v++) {
            for (r = map[v - 1].head; r != NULL;
                 r = (disk_io_req_t *)ARCH_VA_TO_PTR(r->next)) {
                if (r != req) {
                    continue;
                }
                disk_$io_error(v, req, hdr);
                if (req->status == status_$disk_ok_after_device_recovery ||
                    req->status == status_$disk_ok_after_retry ||
                    req->status == status_$disk_ok_after_crc_correction) {
                    req->status = status_$ok;
                    goto check;                           /* 0x00E3D256 */
                }
                goto done;                                /* 0x00E3D250 */
            }
        }

    next:
        /* 0x00E3D26A-0x00E3D274 */
        hdr[2]++;
        (*pages_read)++;
        req = (disk_io_req_t *)ARCH_VA_TO_PTR(req->free_next);
    }

done:
    /* 0x00E3D280-0x00E3D288 */
    *status = head->status;
}
